    fn bundled_deps_falls_back_to_alias_only() {
        let v = parse(r#"{"name":"x","version":"1.0.0","bundleDependencies":["legacy"]}"#);
        let deps = BTreeMap::new();
        let names = v.bundled_dependencies.as_ref().unwrap().names(&deps);
